const ctx = $json;
const p = ctx.patient || {};
const clinic = ctx.clinic || {};
const ready = !!(p.name && p.phone);
const day = $now.format('yyyy-LL-dd');
const leadKey = `${clinic.clinic_id}|${p.phone || 'nophone'}|appointment|${day}`;
const svc = p.service || 'a visit';

let reply;
if (ready) {
  reply = `Thanks ${p.name}! I've sent your request for ${svc} to our team. Please note this is a request only — we can't confirm a time here. Our team will contact you at ${p.phone} to confirm availability. Anything else I can help with?`;
} else {
  reply = (ctx.next_question && ctx.next_question.trim())
    ? ctx.next_question
    : `I'd be glad to help you request an appointment. Could you share your full name and the best phone number to reach you?`;
}

const apptRow = {
  tab: 'Appointment_Requests', operation: 'upsert', sheet_id: clinic.sheet_id,
  lead_key: leadKey, created_at: ctx.timestamp || $now.toISO(), session_id: ctx.session_id,
  patient_name: p.name || '', phone: p.phone || '', email: p.email || '',
  patient_type: p.patient_type || '', requested_service: p.service || '',
  preferred_date: p.preferred_date || '', preferred_time: p.preferred_time || '',
  urgency: ctx.urgency || 'medium', status: ready ? 'New' : 'Collecting',
  conversation_summary: (clinic.test_mode ? '[TEST] ' : '') + (ctx.summary || ''),
  staff_notified: ready, sms_sent: false, last_updated: $now.toISO()
};

const emailBody = `Request type: Appointment request\nUrgency: ${ctx.urgency}\nPatient: ${p.name}\nPhone: ${p.phone}\nEmail: ${p.email || '-'}\nPatient type: ${p.patient_type || '-'}\nService: ${p.service || '-'}\nPreferred: ${p.preferred_date || '-'} ${p.preferred_time || ''}\n\nSummary: ${ctx.summary}\nOriginal message: "${ctx.user_message}"\n\nRecommended next action: Contact the patient to confirm availability. (Not yet confirmed.)`;
const email = { to: clinic.staff_email, subject: `[${clinic.clinic_name}] Appointment request — ${ctx.urgency} — ${p.name}`, body: (clinic.test_mode ? '[TEST MODE]\n' : '') + emailBody, reply_to: p.email || '' };

const smsBody = `Hi ${p.name}, thanks for contacting ${clinic.clinic_name}. We received your appointment request for ${svc}. Our team will contact you to confirm availability.`;
const sms = { to: p.phone, body: smsBody, message_type: 'appointment_received', from: clinic.twilio_from, enabled: clinic.sms_enabled_patient, session_id: ctx.session_id, sheet_id: clinic.sheet_id };

return { json: { ...ctx, bot_response: reply, _ready: ready, _apptRow: apptRow, _email: email, _sms: sms } };
